from repo.histogram import bucket_of
from repo.rows import histogram_summary

assert bucket_of(30, 10, 3) == 2
assert bucket_of(31, 10, 3) == 2
assert bucket_of(-1, 10, 3) == 0
assert bucket_of(5.0, 10, 3) == 0
assert isinstance(bucket_of(5.0, 10, 3), int)
assert histogram_summary([-1, 0, 5.0, 10, 29, 30, 100], 10, 3) == {
    'n': 7,
    'counts': [3, 1, 3],
}
for args in ((1, 0, 3), (1, -1, 3), (1, 10, 0), (1, 10, -1)):
    try:
        bucket_of(*args)
    except ValueError:
        pass
    else:
        raise AssertionError(args)
